def score(program: str) -> float:
    import ast
    try:
        return min(1.0, sum(1 for _ in ast.walk(ast.parse(program))) / 150.0)
    except:
        return 0.0

def score(program: str) -> float:
    import ast
    try:
        t = ast.parse(program)
        n = len(list(ast.walk(t)))
        return max(0, 1 - abs(n - 60) / 100)
    except:
        return 0.5

